import{z as s,x as d,o as n,c as B,q as o,j as r,D as t,d as l,s as E,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"WebAuthn / FIDO2","description":"","frontmatter":{"title":"WebAuthn / FIDO2","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/webauthn-fido2.md","filePath":"cs/webauthn-fido2.md","lastUpdated":1791063341000}'),h={name:"cs/webauthn-fido2.md"};function p(u,a,c,D,m,b){const i=d("Mermaid");return n(),B("div",null,[a[2]||(a[2]=o('<h1 id="webauthn-fido2" tabindex="-1">WebAuthn / FIDO2 <a class="header-anchor" href="#webauthn-fido2" aria-label="Permalink to &quot;WebAuthn / FIDO2&quot;">​</a></h1><div class="epigraph"><p>WebAuthn 让浏览器把挑战交给认证器：私钥不出盒，站点拿到的是源绑定的公钥凭证。钓鱼站点换源就验不过，这是对共享口令模型的结构性修补。</p><footer>—— W3C Web Authentication；FIDO Alliance CTAP；对照 RFC 6238 仍只是第二因素</footer></div><p>上一课<a href="/cs/saml">SAML</a>仍常与口令 IdP 搭配。缺口是<strong>源绑定公钥</strong>：凭据属于 <code>https://example.com</code>，不是用户可粘贴的秘密。本课收登记与断言，不写破解认证器的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口令可被钓鱼页收集。WebAuthn：RP ID、challenge、user verification、attestation（可选）。缺口是丢失设备与恢复流程——恢复若退回邮箱口令，钓鱼面回来。</p><p><span class="marginnote">术语翻译：RP ID 就是「这把钥匙归哪个网站」的标签——认证器签名前先核对浏览器报来的 origin 与标签一致才肯动手；凭据像刻了门牌号的钥匙，换一扇门就插不进锁。</span></p><h3 id="不是生物识别本身" tabindex="-1">不是生物识别本身 <a class="header-anchor" href="#不是生物识别本身" aria-label="Permalink to &quot;不是生物识别本身&quot;">​</a></h3><p>指纹/面容是认证器本地解锁。服务器只看见签名成功，不应存储生物模板。FAR/FRR 更后一课。</p><p><span class="marginnote">W3C WebAuthn Level 2/3。平台认证器与只安全密钥。本课不提供克隆密钥的指导。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分 ceremony：create 与 get。强调 challenge 防重放、origin 由浏览器填。服务器存公钥与计数器（克隆检测点名）。对照 TOTP：仍是共享秘密，可被钓鱼同时转发。</p>',12)),(n(),r(A,null,{default:t(()=>[E(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RP%5B%22%E7%AB%99%E7%82%B9%20origin%22%5D%20--%3E%20CH%5B%22challenge%22%5D%0A%20%20CH%20--%3E%20AUTH%5B%22%E8%AE%A4%E8%AF%81%E5%99%A8%E7%AD%BE%22%5D%0A%20%20AUTH%20--%3E%20PUB%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E9%AA%8C%E5%85%AC%E9%92%A5%22%5D%0A%20%20ORIGIN%5B%22%E6%BA%90%E7%BB%91%E5%AE%9A%22%5D%20--%3E%20PUB%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"身份因素从「知道」转向「持有+本地解锁」。账户恢复、企业托管与备份密钥是治理，不是协议算术。下一课 TOTP 与 MFA：仍广泛部署的共享秘密第二因素。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：challenge 是服务器随机发的 32 字节 nonce，签名报文里原样带回；同一 challenge 第二次出现即作废——攻击者录下整段签名也无法用它通过下一次登录。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：以为指纹/面容就是认证凭据——生物特征只在设备本地解锁私钥，服务器只见到一次签名验证结果；生物模板不出设备，指纹可重录，真正要保住的是那把不出盒的私钥。")],-1)),(n(),r(A,null,{default:t(()=>[E(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E7%9C%9F%E7%AB%99%20example.com%20%E5%8F%91%E8%B5%B7%20get%22%5D%20--%3E%20LB%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%E5%A1%AB%20origin%3Dexample.com%22%5D%0A%20%20LB%20--%3E%20LM%5B%22RP%20ID%20%E5%8C%B9%E9%85%8D%EF%BC%8C%E8%AE%A4%E8%AF%81%E5%99%A8%E5%87%BA%E7%AD%BE%E5%90%8D%22%5D%0A%20%20PH%5B%22%E9%92%93%E9%B1%BC%E7%AB%99%20evil.com%20%E5%A4%8D%E5%88%B6%E7%99%BB%E5%BD%95%E9%A1%B5%22%5D%20--%3E%20PB%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%E5%A1%AB%20origin%3Devil.com%22%5D%0A%20%20PB%20--%3E%20PM%5B%22RP%20ID%20%E4%B8%8D%E5%8C%B9%E9%85%8D%EF%BC%8C%E8%AE%A4%E8%AF%81%E5%99%A8%E6%8B%92%E7%AD%BE%22%5D%0A%20%20PM%20--%3E%20X%5B%22%E9%92%93%E9%B1%BC%E8%80%85%E6%8B%BF%E4%B8%8D%E5%88%B0%E5%8F%AF%E7%94%A8%E7%AD%BE%E5%90%8D%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CTAP hid 细节。TOTP 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SAML/OAuth 常仍站在口令上；WebAuthn 源绑定密钥。</li><li>私钥不出认证器；challenge 防重放。</li><li>恢复流程可能把钓鱼面请回来。</li><li>下一课 TOTP 与 MFA。</li><li>出处：W3C Web Authentication；FIDO CTAP；对照 RFC 6238。</li></ul>',4))])}const T=s(h,[["render",p]]);export{f as __pageData,T as default};
